 const path = require('path');
 const fs = require('fs');
 const http = require('http');

 (async () => {
   const server = http.createServer((req, res) => {
     let filePath = '.' + req.url.split('?')[0];
     if (filePath === './') filePath = './index.html';

     const extname = path.extname(filePath);
     let contentType = 'text/html';
     switch (extname) {
       case '.js': contentType = 'text/javascript'; break;
       case '.css': contentType = 'text/css'; break;
     }

     fs.readFile(path.join(__dirname, filePath), (err, content) => {
       if (err) {
         res.writeHead(404);
         res.end('Not found');
       } else {
         res.writeHead(200, { 'Content-Type': contentType });
         res.end(content, 'utf-8');
       }
     });
   }).listen(0);

   const port = server.address().port;
   const browser = await chromium.launch();
   const page = await browser.newPage();

   page.on('console', msg => console.log('BROWSER LOG:', msg.text()));
   page.on('pageerror', err => console.log('BROWSER ERROR:', err.message));

   await page.goto(`http://localhost:${port}`, { waitUntil: 'networkidle' });
   await page.waitForSelector('#root .form-container', { timeout: 15000 });

   const axeSource = fs.readFileSync(path.join(__dirname, 'node_modules/axe-core/axe.min.js'), 'utf8');
   await page.evaluate(axeSource);

   const results = await page.evaluate(async () => {
     return await window.axe.run();
   });

   fs.writeFileSync('a11y-report.json', JSON.stringify(results, null, 2));

   await browser.close();
   server.close();

   if (results.violations.length > 0) {
     process.exit(1);
   }
 })();

