 const { useState, useRef } = React;

 const ContactForm = () => {
   const [formData, setFormData] = useState({
     fullName: '',
     email: '',
     phone: ''
   });

   const [errors, setErrors] = useState({});
   const [touched, setTouched] = useState({});
   const [submitted, setSubmitted] = useState(false);

   const nameRef = useRef(null);
   const emailRef = useRef(null);
   const phoneRef = useRef(null);

   const validate = (name, value) => {
     let error = '';
     if (name === 'fullName') {
       if (!value.trim()) error = 'Error: Full name is required.';
     } else if (name === 'email') {
       if (!value.trim()) {
         error = 'Error: Email address is required.';
       } else if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(value)) {
         error = 'Error: Enter a valid email address (e.g., name@example.com).';
       }
     } else if (name === 'phone') {
       if (value && !/^\+?[0-9\s\-()]{7,20}$/.test(value)) {
         error = 'Error: Enter a valid phone number.';
       }
     }
     return error;
   };

   const handleChange = (e) => {
     const { name, value } = e.target;
     setFormData(prev => ({ ...prev, [name]: value }));

     if (touched[name]) {
       const error = validate(name, value);
       setErrors(prev => ({ ...prev, [name]: error }));
     }
   };

   const handleBlur = (e) => {
     const { name, value } = e.target;
     setTouched(prev => ({ ...prev, [name]: true }));
     const error = validate(name, value);
     setErrors(prev => ({ ...prev, [name]: error }));
   };

   const handleSubmit = (e) => {
     e.preventDefault();

     const newErrors = {
       fullName: validate('fullName', formData.fullName),
       email: validate('email', formData.email),
       phone: validate('phone', formData.phone)
     };

     setErrors(newErrors);
     setTouched({ fullName: true, email: true, phone: true });

     const firstError = Object.keys(newErrors).find(key => newErrors[key]);
     if (firstError) {
       if (firstError === 'fullName') nameRef.current.focus();
       else if (firstError === 'email') emailRef.current.focus();
       else if (firstError === 'phone') phoneRef.current.focus();
       return;
     }

     // Success
     setSubmitted(true);
   };

   if (submitted) {
     return (
       <div className="form-container" role="status" aria-live="polite">
         <h2>Message Sent!</h2>
         <p>Thank you, {formData.fullName}. We've received your request and will get back to you at {formData.email} soon.</p>
         <button onClick={() => setSubmitted(false)} type="button">Send another message</button>
       </div>
     );
   }

   return (
     <div className="form-container">
       <form onSubmit={handleSubmit} novalidate>
         <div className="form-field">
           <label htmlFor="fullName">
             Full Name <span className="required-marker" aria-hidden="true">*</span>
             <span className="sr-only">(required)</span>
           </label>
           <input
             ref={nameRef}
             type="text"
             id="fullName"
             name="fullName"
             value={formData.fullName}
             onChange={handleChange}
             onBlur={handleBlur}
             required
             autocomplete="name"
             aria-invalid={!!errors.fullName}
             aria-describedby={errors.fullName ? "fullName-error" : undefined}
           />
           {errors.fullName && (
             <p id="fullName-error" className="error-message">{errors.fullName}</p>
           )}
         </div>

         <div className="form-field">
           <label htmlFor="email">
             Email Address <span className="required-marker" aria-hidden="true">*</span>
             <span className="sr-only">(required)</span>
           </label>
           <input
             ref={emailRef}
             type="email"
             id="email"
             name="email"
             value={formData.email}
             onChange={handleChange}
             onBlur={handleBlur}
             required
             autocomplete="email"
             aria-invalid={!!errors.email}
             aria-describedby={errors.email ? "email-error" : undefined}
           />
           {errors.email && (
             <p id="email-error" className="error-message">{errors.email}</p>
           )}
         </div>

         <div className="form-field">
           <label htmlFor="phone">
             Phone Number (optional)
           </label>
           <input
             ref={phoneRef}
             type="tel"
             id="phone"
             name="phone"
             value={formData.phone}
             onChange={handleChange}
             onBlur={handleBlur}
             autocomplete="tel"
             aria-invalid={!!errors.phone}
             aria-describedby={`phone-help ${errors.phone ? "phone-error" : ""}`}
           />
           <p id="phone-help" className="helper-text">Format: +1 (555) 000-0000</p>
           {errors.phone && (
             <p id="phone-error" className="error-message">{errors.phone}</p>
           )}
         </div>

         <button type="submit">Send Message</button>
       </form>
     </div>
   );
 };

 const root = ReactDOM.createRoot(document.getElementById('root'));
 root.render(<ContactForm />);

